/// <summary>
/// N.Freidenberger 03.09.2025
/// </summary>
/// <returns>boolean</returns>
protected boolean check()
{
    boolean ok;
    boolean  locCheckOk;

    ok = next check();

    ok = ok && salesTable.avaCheckMarkupFreightInformationBeforeIPost();

    locCheckOk = salesTable.avaCheckFreightInformationBeforeIPost(false);
    if(!locCheckOk)
    {
        checkFailed(strFmt("@NDX:NXASalesOrderP1FreightCostMissung", salesTable.SalesId));
    }
    ok = ok && locCheckOk;

    return ok;
}
